import express from 'express';
// Trigger DB Reconnect 4
import http from 'http';
import { Server } from 'socket.io';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { createClient } from 'redis';
import { config } from './src/config/livekit.js';
import * as roomController from './src/controllers/roomController.js';
import * as telemetryController from './src/controllers/telemetryController.js';
import logger from './src/config/logger.js';
import { connectDB } from './src/config/db.js';

// Route Imports
import authRoutes from './src/routes/authRoutes.js';
import configRoutes from './src/routes/configRoutes.js';
import roomRoutes from './src/routes/roomRoutes.js';
import telemetryRoutes from './src/routes/telemetryRoutes.js';
import crawlerRoutes from './src/routes/crawlerRoutes.js';
import githubRoutes from './src/routes/githubRoutes.js';
import careersRoutes from './src/routes/careersRoutes.js';
import battleRoutes from './src/routes/battleRoutes.js';
import changelogRoutes from './src/routes/changelogRoutes.js';
import docsRoutes from './src/routes/docsRoutes.js';
import delhiveryRoutes from './src/routes/delhiveryRoutes.js';
import { registerBattleSockets } from './src/sockets/battleSocket.js';
import agentsRoutes from './src/routes/agentsRoutes.js';
import { startMetricsMonitor } from './src/services/monitorService.js';

// API platform middleware
import { requestContext } from './src/middlewares/requestContext.js';
import { securityHeaders, corsPolicy, globalRateLimiter } from './src/middlewares/httpSecurity.js';
import { notFoundHandler, errorHandler } from './src/middlewares/errorHandler.js';

// Global console redirection to Pino structured JSON logger for high-throughput enterprise performance
console.log = (...args) => logger.info(args.join(' '));
console.info = (...args) => logger.info(args.join(' '));
console.warn = (...args) => logger.warn(args.join(' '));
console.error = (...args) => {
  if (args[0] instanceof Error) {
    logger.error({ err: args[0] }, args[0].message);
  } else {
    logger.error(args.join(' '));
  }
};

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
// Trust proxy only when explicitly configured (e.g. behind a load balancer)
// so client IPs for rate limiting cannot be spoofed via X-Forwarded-For.
app.set('trust proxy', process.env.TRUST_PROXY ? Number(process.env.TRUST_PROXY) : false);
app.use(securityHeaders);
app.use(requestContext);
app.use(corsPolicy());
app.use(globalRateLimiter);
app.use(express.json({ limit: '10mb' }));

const httpServer = http.createServer(app);
const socketOrigins = (process.env.CORS_ORIGINS || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
const io = new Server(httpServer, {
  cors: {
    origin: socketOrigins.length ? socketOrigins : "*",
    methods: ["GET", "POST"]
  }
});

io.on("connection", (socket) => {
  console.log(`[SOCKET] Client connected: ${socket.id}`);
  socket.on("disconnect", () => {
    console.log(`[SOCKET] Client disconnected: ${socket.id}`);
  });
});

// --- REDIS TELEMETRY BRIDGE ---
const redisClient = createClient({
  url: process.env.REDIS_URL || 'redis://localhost:6379',
  socket: {
    reconnectStrategy: (retries) => {
      // Reconnect indefinitely with backoff, max 3 seconds delay
      return Math.min(retries * 100, 3000);
    }
  }
});
redisClient.on('error', (err) => {
  if (err.code !== 'ECONNREFUSED') {
    console.error('Redis Client Error', err.message);
  }
});

try {
  await redisClient.connect();
  logger.info('[REDIS] ✅ Connected to Redis successfully.');
  await redisClient.subscribe('octane_telemetry_stream', (message) => {
    try {
      const payload = JSON.parse(message);
      if (payload.alert === true) {
        console.log("[REDIS ALERT] Forwarding alert to frontend clients.");
        io.emit("backend_error", { type: "RUNTIME_ALERT", message: payload.line, timestamp: payload.timestamp });
      }
    } catch(e) {
      // ignore parse error
    }
  });
} catch (redisErr) {
  logger.warn(`[REDIS] ⚠️  Redis connection failed: ${redisErr.message}`);
  logger.warn('[REDIS] Octane telemetry bridge is offline. Server continues without real-time Redis alerts.');
}


// --- GLOBAL ERROR TELEMETRY ---
const logBackendError = (type, error) => {
  const timestamp = new Date().toISOString();
  const errorMsg = error instanceof Error ? error.stack || error.message : String(error);

  const logEntry = `[${timestamp}] [${type}] ${errorMsg}\n`;
  const logPath = path.resolve(__dirname, "../backend_errors.log");

  // Asynchronous append to avoid event loop blocking
  fs.appendFile(logPath, logEntry, 'utf8', (err) => {
    if (err) {
      console.error(`[TELEMETRY] Failed to write error log:`, err);
    } else {
      console.error(`[TELEMETRY] ${type} appended to backend_errors.log`);
    }
  });
  io.emit("backend_error", { type, message: errorMsg, timestamp });
};

process.on("uncaughtException", (err) => {
  logBackendError("UNCAUGHT_EXCEPTION", err);
  // Graceful exit for enterprise reliability (PM2 or Kubernetes restarts the process)
  setTimeout(() => process.exit(1), 1000);
});

process.on("unhandledRejection", (reason) => {
  logBackendError("UNHANDLED_REJECTION", reason);
});

// Inject io instance into the controllers
roomController.setSocketIO(io);
telemetryController.setSocketIO(io);
registerBattleSockets(io);
startMetricsMonitor(io);

// Connect to Database
await connectDB();

// --- ROUTE MOUNTINGS (legacy/stable surface — preserved for backward compatibility) ---
app.use('/api/auth', authRoutes);
app.use('/api/crawler', crawlerRoutes);
app.use('/api/github', githubRoutes);
app.use('/api/careers', careersRoutes);
app.use('/api/battle', battleRoutes);
app.use('/api/changelog', changelogRoutes); // Reconciled: was only mounted in the dead src/app.js
app.use('/api', configRoutes);
app.use('/api', telemetryRoutes); // Mounts /api/llm-trace, /api/llm-traces, /api/evaluate-hallucination, etc.
app.use('/', telemetryRoutes);   // Mounts root-level routes: /security/status, /security/scan, /security/remediate, /detokenize
app.use('/', roomRoutes);        // Mounts root-level routes: /talk-to-ai, /trigger-reels, /copilot/chat, /copilot/session/clear
app.use('/api/delhivery', delhiveryRoutes);
app.use('/api/agents', agentsRoutes);


// --- VERSIONED SURFACE (/api/v1) — additive aliases for new clients; legacy paths above remain valid ---
app.use('/api/v1/auth', authRoutes);
app.use('/api/v1/crawler', crawlerRoutes);
app.use('/api/v1/github', githubRoutes);
app.use('/api/v1/careers', careersRoutes);
app.use('/api/v1/battle', battleRoutes);
app.use('/api/v1/changelog', changelogRoutes);
app.use('/api/v1', configRoutes);
app.use('/api/v1', telemetryRoutes);
app.use('/api/v1', roomRoutes);
app.use('/api/v1/delhivery', delhiveryRoutes);


// --- API DOCUMENTATION (Swagger UI + raw OpenAPI 3.1 spec) ---
if (process.env.ENABLE_API_DOCS !== 'false') {
  app.use('/api', docsRoutes); // GET /api/docs and GET /api/openapi.json
}

// --- TERMINAL HANDLERS (must be registered after all routes) ---
app.use(notFoundHandler);
app.use(errorHandler);

httpServer.listen(config.port, "0.0.0.0", () => {
  console.log(`[ENTERPRISE] Business Layers Active on ${config.port}`);
  console.log(`[ENTERPRISE] LiveKit Target: ${config.livekit.url}`);
});

import pg from 'pg';
import logger from './logger.js';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { exec } from 'child_process';
import util from 'util';

const { Pool } = pg;
const execPromise = util.promisify(exec);

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

let pool = null;

export const connectDB = async () => {
  const connectionString = process.env.DATABASE_URL || 'postgresql://postgres@127.0.0.1:5433/swarm';
  try {
    pool = new Pool({
      connectionString,
      connectionTimeoutMillis: 5000,
    });

    pool.on('error', (err) => {
      logger.error(`[DATABASE] Unexpected error on idle client: ${err.message}`);
    });

    // Test connection
    const client = await pool.connect();
    logger.info(`[DATABASE] ✅ PostgreSQL Connected Successfully.`);

    // Initialize Tables
    await initializeTables(client);

    client.release();
  } catch (error) {
    logger.warn(`[DATABASE] ⚠️  PostgreSQL connection failed: ${error.message}`);
    logger.warn(`[DATABASE] Server will continue without database. Auth endpoints will be unavailable until PostgreSQL is running.`);
  }
};

const initializeTables = async (client) => {
  try {
    // 1. Create Users table
    await client.query(`
      CREATE TABLE IF NOT EXISTS users (
        id SERIAL PRIMARY KEY,
        username VARCHAR(255) NOT NULL,
        email VARCHAR(255) UNIQUE NOT NULL,
        password_hash VARCHAR(255) NOT NULL,
        role VARCHAR(50) DEFAULT 'operator' CHECK (role IN ('admin', 'operator', 'viewer')),
        company_name VARCHAR(255) DEFAULT 'Nexus Swarm Operator',
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 2. Create Sessions table
    await client.query(`
      CREATE TABLE IF NOT EXISTS sessions (
        id SERIAL PRIMARY KEY,
        user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
        room_name VARCHAR(255) NOT NULL,
        agent_type VARCHAR(255) NOT NULL,
        started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        ended_at TIMESTAMP WITH TIME ZONE NULL,
        primary_interests JSONB DEFAULT '[]'::jsonb,
        status VARCHAR(50) DEFAULT 'active' CHECK (status IN ('active', 'completed', 'disconnected'))
      );
    `);

    // 3. Create Traces table
    await client.query(`
      CREATE TABLE IF NOT EXISTS traces (
        id SERIAL PRIMARY KEY,
        run_id VARCHAR(255) UNIQUE NOT NULL,
        input_id VARCHAR(32) NULL,
        output_id VARCHAR(24) NULL,
        agent VARCHAR(255) NULL,
        model VARCHAR(255) DEFAULT 'unknown',
        inputs JSONB DEFAULT '[]'::jsonb,
        outputs TEXT DEFAULT '',
        prompt_tokens INTEGER DEFAULT 0,
        completion_tokens INTEGER DEFAULT 0,
        input_cost NUMERIC DEFAULT 0,
        output_cost NUMERIC DEFAULT 0,
        stt_cost NUMERIC DEFAULT 0,
        tts_cost NUMERIC DEFAULT 0,
        total_cost NUMERIC DEFAULT 0,
        status VARCHAR(50) DEFAULT 'streaming' CHECK (status IN ('streaming', 'completed', 'failed')),
        timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        total_latency NUMERIC DEFAULT 0,
        ttft NUMERIC DEFAULT 0,
        tool_latency NUMERIC DEFAULT 0,
        otps NUMERIC DEFAULT 0,
        tool_calls JSONB DEFAULT '[]'::jsonb,
        error_details JSONB DEFAULT '{}'::jsonb
      );
    `);

    // Safe migration: add input_id / output_id to existing tables (no-op if already present)
    await client.query(`
      ALTER TABLE traces
        ADD COLUMN IF NOT EXISTS input_id  VARCHAR(32) NULL,
        ADD COLUMN IF NOT EXISTS output_id VARCHAR(24) NULL;
    `);

    // 4. Create Password Reset Tokens table
    await client.query(`
      CREATE TABLE IF NOT EXISTS password_reset_tokens (
        id SERIAL PRIMARY KEY,
        user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
        token VARCHAR(255) UNIQUE NOT NULL,
        expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
        used BOOLEAN DEFAULT FALSE,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 5. Create Copilot Sessions table
    await client.query(`
      CREATE TABLE IF NOT EXISTS copilot_sessions (
        session_id VARCHAR(255) PRIMARY KEY,
        session_data JSONB NOT NULL,
        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 6. Create Crawling Configs table
    await client.query(`
      CREATE TABLE IF NOT EXISTS crawling_configs (
        id VARCHAR(50) PRIMARY KEY,
        start_url VARCHAR(1024) NOT NULL,
        include_pattern VARCHAR(255),
        exclude_pattern VARCHAR(255),
        sitemap_enabled BOOLEAN DEFAULT TRUE,
        custom_sitemap VARCHAR(1024),
        js_rendering BOOLEAN DEFAULT FALSE,
        proxy_enabled BOOLEAN DEFAULT FALSE,
        extract_pdfs BOOLEAN DEFAULT FALSE,
        main_css VARCHAR(559),
        exclude_css VARCHAR(559),
        template VARCHAR(50),
        last_crawled_at TIMESTAMP WITH TIME ZONE,
        status VARCHAR(50) DEFAULT 'idle',
        last_error TEXT,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 7. Create GitHub Configs table
    await client.query(`
      CREATE TABLE IF NOT EXISTS github_configs (
        id VARCHAR(50) PRIMARY KEY,
        owner VARCHAR(255) NOT NULL,
        name VARCHAR(255) NOT NULL,
        token VARCHAR(255),
        branch_or_tag VARCHAR(255),
        file_types TEXT[],
        directories TEXT[],
        file_include_regex VARCHAR(1024),
        file_exclude_regex VARCHAR(1024),
        last_ingested_at TIMESTAMP WITH TIME ZONE,
        status VARCHAR(50) DEFAULT 'idle',
        last_error TEXT,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 8. Create Compliance Logs table
    await client.query(`
      CREATE TABLE IF NOT EXISTS compliance_logs (
        id SERIAL PRIMARY KEY,
        event_type VARCHAR(100) NOT NULL,
        severity VARCHAR(50) NOT NULL,
        agent VARCHAR(255) NULL,
        details JSONB DEFAULT '{}'::jsonb,
        timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 9. Create Indexes for traces
    await client.query(`
      CREATE INDEX IF NOT EXISTS idx_traces_timestamp ON traces(timestamp DESC);
      CREATE INDEX IF NOT EXISTS idx_traces_agent ON traces(agent);
      CREATE INDEX IF NOT EXISTS idx_traces_run_id ON traces(run_id);
    `);

    // 10. Create NIST AI RMF Core Master table
    await client.query(`
      CREATE TABLE IF NOT EXISTS nist_rmf_core (
        id SERIAL PRIMARY KEY,
        function VARCHAR(100) NOT NULL,
        category TEXT NOT NULL,
        subcategory_id VARCHAR(50) UNIQUE NOT NULL,
        description TEXT NOT NULL,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 11. Create Agent Analysis table
    await client.query(`
      DROP TABLE IF EXISTS agent_analysis CASCADE;
      CREATE TABLE IF NOT EXISTS agent_analysis (
        id SERIAL PRIMARY KEY,
        agent_name VARCHAR(255) UNIQUE NOT NULL,
        agent_type VARCHAR(100) NOT NULL,
        business_function VARCHAR(100) NOT NULL,
        autonomy VARCHAR(50) NOT NULL,
        risk_tier VARCHAR(50) NOT NULL,
        capabilities TEXT[] NOT NULL,
        data_classes TEXT[] NOT NULL,
        external_reach TEXT[] NOT NULL,
        applicable_controls TEXT[] NOT NULL,
        non_applicable_controls TEXT[] NOT NULL,
        applicable_count INTEGER NOT NULL,
        non_applicable_count INTEGER NOT NULL,
        unmapped_count INTEGER NOT NULL DEFAULT 0,
        control_map JSONB NOT NULL,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 12. Create Agent Security Status table
    await client.query(`
      CREATE TABLE IF NOT EXISTS agent_security_status (
        agent_name VARCHAR(255) PRIMARY KEY,
        timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        critical_count INTEGER DEFAULT 0,
        warning_count INTEGER DEFAULT 0,
        report_summary JSONB DEFAULT '[]'::jsonb,
        nist_score NUMERIC DEFAULT 100,
        nist_risk VARCHAR(50) DEFAULT 'LOW',
        nist_controls JSONB DEFAULT '[]'::jsonb
      );
    `);

    // 13. Create OWASP LLM Core Master table
    await client.query(`
      CREATE TABLE IF NOT EXISTS owasp_llm_core (
        id SERIAL PRIMARY KEY,
        framework VARCHAR(100) NOT NULL,
        control_id VARCHAR(50) UNIQUE NOT NULL,
        category VARCHAR(255) NOT NULL,
        description TEXT NOT NULL,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 14. Create Careers Applications table
    await client.query(`
      CREATE TABLE IF NOT EXISTS careers_applications (
        id SERIAL PRIMARY KEY,
        role_id VARCHAR(255) NOT NULL,
        role_title VARCHAR(255) NOT NULL,
        name VARCHAR(255) NOT NULL,
        email VARCHAR(255) NOT NULL,
        mobile VARCHAR(50) NULL,
        portfolio VARCHAR(1024) NULL,
        message TEXT NOT NULL,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // Migrate: Add resume_data column if not exists
    await client.query(`
      ALTER TABLE careers_applications
        ADD COLUMN IF NOT EXISTS resume_data JSONB NULL,
        ADD COLUMN IF NOT EXISTS mobile VARCHAR(50) NULL,
        ADD COLUMN IF NOT EXISTS battle_token VARCHAR(50) UNIQUE DEFAULT NULL,
        ADD COLUMN IF NOT EXISTS battle_token_used BOOLEAN DEFAULT FALSE;
    `);

    // 15. Create Battle Arena Questions Table
    await client.query(`
      CREATE TABLE IF NOT EXISTS battle_questions (
        id VARCHAR(50) PRIMARY KEY,
        topic VARCHAR(255) NOT NULL,
        question TEXT NOT NULL,
        grading_rubric JSONB NOT NULL,
        model_answer TEXT NOT NULL,
        role_id VARCHAR(50) DEFAULT 'ai-pm',
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
      );
    `);

    // 16. Create Battle Arena Answered Questions tracking Table
    await client.query(`
      CREATE TABLE IF NOT EXISTS battle_answered_questions (
        id SERIAL PRIMARY KEY,
        email VARCHAR(255) NOT NULL,
        question_id VARCHAR(50) NOT NULL,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        UNIQUE (email, question_id)
      );
    `);

    // Seed/sync static AI-PM questions
    logger.info('[DATABASE] ⏳ Syncing static AI-PM challenge questions...');
    const pmQuestions = [
      {
        id: "SWARM_01",
        topic: "LiveKit Latency & Conversational UX (Barge-in)",
        question: "A user is speaking to our Swarm via LiveKit. Our STT processes the text, passes it to the Orchestrator, which queries RAG, sends it to the LLM, and streams to TTS. The total round-trip latency is 2.5 seconds, making the conversation feel unnatural. Worse, when the user interrupts (barge-in), the TTS keeps speaking for 2 seconds. How do you fix the latency and the barge-in UX?",
        grading_rubric: [
          "Proposes semantic chunking/streaming from LLM directly to TTS.",
          "Addresses LiveKit/WebRTC voice activity detection (VAD) for instant TTS cancellation.",
          "Suggests filling the silence with 'filler words' (e.g., 'Hmm', 'Let me check') via a fast, local model."
        ],
        model_answer: "To fix the 2.5s latency, I'd move to a fully streaming pipeline. The LLM shouldn't wait for the full response; it needs to stream token chunks directly into the TTS engine so audio begins playing after the first sentence is generated. For the barge-in issue, the problem is the audio buffer. I would implement strict Voice Activity Detection (VAD) on the LiveKit client side. The millisecond the VAD detects the user speaking, the client must send an interrupt signal to immediately flush the TTS audio buffer and halt the LLM generation to save tokens. Finally, to mask the remaining 500ms network latency, I'd deploy a tiny, local edge model that instantly outputs filler sounds like 'Got it, let me pull that up' while the main Swarm does the heavy lifting."
      },
      {
        id: "SWARM_02",
        topic: "Agent Deadlocks and Infinite Loops",
        question: "In our 20-agent Swarm, Agent A (Research) asks Agent B (Data Analysis) for a summary. Agent B needs more context and queries Agent A. They enter an infinite loop, burning through $50 of LLM tokens in 3 minutes before hitting a hard timeout. How do you architect the orchestration layer to prevent this?",
        grading_rubric: [
          "Introduces a central Orchestrator/Router instead of pure peer-to-peer agent communication.",
          "Implements strict 'Time-to-Live' (TTL) or hop-count limits on agent requests.",
          "Proposes circuit breakers or token-burn alerts."
        ],
        model_answer: "Peer-to-peer agent communication at a 20-agent scale is a recipe for catastrophic token burn. I would transition to a centralized Orchestrator or 'Supervisor' model. Agents shouldn't trigger each other directly; they must return a 'tool_call' request to the Supervisor, which evaluates if the routing makes sense. To physically prevent loops, I'd attach a 'hop-count' metadata tag to every user prompt. If a single prompt gets passed between agents more than 4 times, the Supervisor forces a circuit breaker, halts the chain, and returns a graceful fallback message to the user. I'd also implement a hard token-budget cap per session ID at the API gateway level."
      },
      {
        id: "SWARM_03",
        topic: "Data Conflict: RAG vs. SearxNG",
        question: "A user asks for the latest Q3 financial metrics of a competitor. The internal RAG database (updated last week) says revenue is $40M. The SearxNG agent fetches a press release from 10 minutes ago saying $45M. The Synthesis Agent gets confused and hallucinates an average of $42.5M. How do you handle conflicting multi-source data?",
        grading_rubric: [
          "Implements a source-hierarchy or trust-scoring system.",
          "Forces the LLM to output explicit citations and timestamp comparisons.",
          "Identifies that averaging categorical/factual data is a prompt engineering failure."
        ],
        model_answer: "The Synthesis Agent shouldn't be doing math on facts. This is a routing and prompt engineering failure. I would implement a strict 'Timestamp and Trust' hierarchy in the orchestrator. When passing context to the final LLM, the payload must include metadata: Source, Trust Score, and Timestamp. The system prompt for the Synthesis Agent must explicitly state: 'If data sources conflict, prioritize the most recent timestamp. Never average factual numbers.' In the UX, the TTS should verbally acknowledge the discrepancy: 'Our internal records show $40M, but a press release from today indicates $45M.' This builds

import crypto from 'crypto';
import logger from './logger.js';

let jwtSecret = process.env.JWT_SECRET;

if (!jwtSecret || jwtSecret === 'secret-whitelabel-swarm-key') {
  if (process.env.NODE_ENV === 'production') {
    logger.error('[SECURITY] FATAL: JWT_SECRET environment variable is not configured or uses a weak default key in production mode. Halting server.');
    throw new Error('FATAL: JWT_SECRET environment variable is not configured or uses a weak default key in production mode.');
  }

  logger.warn('[SECURITY] JWT_SECRET is not configured or uses a weak default key! Generating a cryptographically secure random 64-byte secret key for this server instance.');
  jwtSecret = crypto.randomBytes(64).toString('hex');
}

export const JWT_SECRET_KEY = jwtSecret;

import dotenv from 'dotenv';
dotenv.config();

export const config = {
  port: process.env.PORT || 3002,
  livekit: {
    apiKey: process.env.LIVEKIT_API_KEY || "devkey",
    apiSecret: process.env.LIVEKIT_API_SECRET || "secret",
    url: process.env.LIVEKIT_URL || "ws://127.0.0.1:7880"
  }
};

import pino from 'pino';

// Configure log level
const logLevel = process.env.LOG_LEVEL || 'info';

// Configure Pino Logger for high-throughput enterprise performance
const logger = pino({
  level: logLevel,
  base: {
    service: 'backend-server',
    env: process.env.NODE_ENV || 'development'
  },
  timestamp: pino.stdTimeFunctions.isoTime
});

export default logger;

import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import { query } from '../config/db.js';
import { sendPasswordResetEmail } from '../services/emailService.js';
import { JWT_SECRET_KEY } from '../config/jwtConfig.js';
import { ApiError } from '../utils/ApiError.js';
import { asyncHandler } from '../middlewares/errorHandler.js';

const formatUser = (dbUser) => ({
  id: dbUser.id,
  username: dbUser.username,
  email: dbUser.email,
  role: dbUser.role,
  companyName: dbUser.company_name,
  createdAt: dbUser.created_at
});

/**
 * Validate password complexity:
 * - At least 8 characters
 * - At least 1 uppercase letter
 * - At least 1 lowercase letter
 * - At least 1 number
 * - At least 1 special character
 */
export const isPasswordStrong = (pw) => {
  if (!pw || pw.length < 8) return false;
  const hasUpper = /[A-Z]/.test(pw);
  const hasLower = /[a-z]/.test(pw);
  const hasNumber = /\d/.test(pw);
  const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?~`]/.test(pw);
  return hasUpper && hasLower && hasNumber && hasSpecial;
};

export const register = asyncHandler(async (req, res) => {
  const { username, email, password, role, companyName } = req.body;

  if (!isPasswordStrong(password)) {
    throw ApiError.badRequest(
      'Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one number, and one special character.',
      'WEAK_PASSWORD'
    );
  }

  const existingUserRes = await query('SELECT * FROM users WHERE email = $1', [email.toLowerCase()]);
  if (existingUserRes.rows.length > 0) {
    throw ApiError.conflict('User with this email already exists.', 'EMAIL_TAKEN');
  }

  // Set first user as admin by default, otherwise defaults to operator.
  // SECURITY (tracked for the auth/security pass): `role` is currently trusted
  // from the client here, which allows self-elevation. The auth pass will drop
  // it so self-registration can only ever yield a non-privileged role.
  const countRes = await query('SELECT COUNT(*) FROM users');
  const count = parseInt(countRes.rows[0].count, 10);
  const resolvedRole = count === 0 ? 'admin' : (role || 'operator');

  const salt = await bcrypt.genSalt(10);
  const passwordHash = await bcrypt.hash(password, salt);

  const company = companyName || 'Nexus Swarm Operator';

  const insertRes = await query(
    `INSERT INTO users (username, email, password_hash, role, company_name)
     VALUES ($1, $2, $3, $4, $5)
     RETURNING *`,
    [username, email.toLowerCase(), passwordHash, resolvedRole, company]
  );

  const newUser = insertRes.rows[0];

  const token = jwt.sign(
    { id: newUser.id, email: newUser.email, role: newUser.role, companyName: newUser.company_name, username: newUser.username },
    JWT_SECRET_KEY,
    { expiresIn: '2h' }
  );

  res.status(201).json({
    token,
    user: formatUser(newUser)
  });
});

export const login = asyncHandler(async (req, res) => {
  const { email, password } = req.body;

  const userRes = await query('SELECT * FROM users WHERE email = $1', [email.toLowerCase()]);

  // To prevent user enumeration / timing attacks, perform a bcrypt comparison even if the user is not found.
  // This dummy hash uses a typical bcrypt salt/structure.
  const dummyHash = '$2b$10$abcdefghijklmnopqrstuvwxABCDEFGHIJKLMNOPQRSTUVWXYZ1234';

  const user = userRes.rows.length > 0 ? userRes.rows[0] : null;

  const passwordHashToCompare = user ? user.password_hash : dummyHash;
  const isMatch = await bcrypt.compare(password, passwordHashToCompare);

  if (!user || !isMatch) {
    throw ApiError.unauthorized('Invalid email or password.', 'INVALID_CREDENTIALS');
  }

  const token = jwt.sign(
    { id: user.id, email: user.email, role: user.role, companyName: user.company_name, username: user.username },
    JWT_SECRET_KEY,
    { expiresIn: '2h' }
  );

  res.json({
    token,
    user: formatUser(user)
  });
});

