import jwt from 'jsonwebtoken';
import { JWT_SECRET_KEY } from '../config/jwtConfig.js';

export const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required. Please login.' });
  }

  if (token === 'mock-dev-token-bypass' && process.env.NODE_ENV !== 'production') {
    req.user = {
      id: 999,
      username: 'dev_operator',
      email: 'dev@swarm.com',
      role: 'admin',
      companyName: 'Swarm Agentic Lab'
    };
    return next();
  }

  jwt.verify(token, JWT_SECRET_KEY, (err, decoded) => {
    if (err) {
      return res.status(403).json({ error: 'Session expired or invalid token. Please re-authenticate.' });
    }
    req.user = decoded;
    next();
  });
};

export const requireRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !req.user.role) {
      return res.status(401).json({ error: 'Authentication details missing.' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden: Insufficient privileges for this operation.' });
    }

    next();
  };
};

const rateLimitMap = new Map();

// Periodically clean up rate limit map to prevent memory growth (memory leaks)
setInterval(() => {
  const now = Date.now();
  const windowMs = 15 * 60 * 1000;
  for (const [ip, timestamps] of rateLimitMap.entries()) {
    const activeTimestamps = timestamps.filter(t => now - t < windowMs);
    if (activeTimestamps.length === 0) {
      rateLimitMap.delete(ip);
    } else {
      rateLimitMap.set(ip, activeTimestamps);
    }
  }
}, 10 * 60 * 1000).unref(); // runs every 10 mins, unref so it does not keep process alive

/**
 * Sliding window rate limiter to protect auth endpoints from brute-force attempts.
 */
export const authRateLimiter = (limit = 10, windowMs = 15 * 60 * 1000) => {
  return (req, res, next) => {
    const ip = req.ip || req.headers['x-forwarded-for'] || req.socket.remoteAddress;
    const now = Date.now();

    if (!rateLimitMap.has(ip)) {
      rateLimitMap.set(ip, []);
    }

    const timestamps = rateLimitMap.get(ip).filter(t => now - t < windowMs);
    timestamps.push(now);
    rateLimitMap.set(ip, timestamps);

    if (timestamps.length > limit) {
      return res.status(429).json({ 
        error: 'Too many authentication attempts. Please try again in 15 minutes.' 
      });
    }

    next();
  };
};

import logger from '../config/logger.js';
import { ApiError } from '../utils/ApiError.js';

/**
 * Wrap an async controller so any rejected promise is forwarded to the
 * central error handler instead of crashing the request as an unhandled
 * rejection. Usage: router.post('/x', asyncHandler(controller))
 */
export const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

/**
 * Terminal 404 for any route that did not match. Returns a JSON envelope
 * consistent with the error handler rather than Express' default HTML page.
 */
export const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: `Route not found: ${req.method} ${req.originalUrl}`,
    code: 'ROUTE_NOT_FOUND',
    traceId: req.id || null
  });
};

/**
 * Central error handler. Renders a single, consistent envelope:
 *   { error, code, traceId, [details] }
 * - 4xx: caller-facing message is preserved (back-compat for the frontend,
 *   which keys auto-logout off specific 401/403 auth messages).
 * - 5xx: internal message is masked to avoid leaking stack/SQL details.
 */
// eslint-disable-next-line no-unused-vars -- Express identifies error handlers by arity (4 args)
export const errorHandler = (err, req, res, next) => {
  let statusCode = err.statusCode || err.status || 500;
  let code = err.code || 'INTERNAL_ERROR';
  let message = err.message || 'An internal server error occurred.';
  let details = err.details;

  // Normalise common framework/parser errors into the same envelope.
  if (err.type === 'entity.parse.failed') {
    statusCode = 400; code = 'INVALID_JSON'; message = 'Malformed JSON in request body.';
  } else if (err.type === 'entity.too.large') {
    statusCode = 413; code = 'PAYLOAD_TOO_LARGE'; message = 'Request body exceeds the allowed size limit.';
  }

  const expose = err instanceof ApiError ? err.expose : statusCode < 500;
  if (!expose) {
    message = 'An internal server error occurred.';
    details = undefined;
  }

  const log = req.log || logger;
  const logPayload = { reqId: req.id, code, statusCode, path: req.originalUrl, method: req.method };
  if (statusCode >= 500) {
    log.error({ ...logPayload, err }, `[API] ${statusCode} ${code}: ${err.message}`);
  } else {
    log.warn(logPayload, `[API] ${statusCode} ${code}: ${err.message}`);
  }

  if (res.headersSent) {
    return next(err);
  }

  const body = { error: message, code, traceId: req.id || null };
  if (details !== undefined) body.details = details;
  res.status(statusCode).json(body);
};

import helmet from 'helmet';
import cors from 'cors';
import rateLimit from 'express-rate-limit';
import logger from '../config/logger.js';

/**
 * Security/transport headers. The backend is a JSON API (the SPA is served
 * separately by Vite), so HTML-oriented policies are relaxed to avoid
 * interfering with cross-origin XHR/fetch while keeping the hardening headers.
 */
export const securityHeaders = helmet({
  contentSecurityPolicy: false,
  crossOriginResourcePolicy: false
});

/**
 * CORS policy.
 * - If CORS_ORIGINS is set (comma-separated), only those origins are allowed
 *   and credentials are permitted.
 * - If unset, falls back to the permissive default (preserves existing
 *   behaviour) but logs a warning so it is visible in non-dev environments.
 */
export const corsPolicy = () => {
  const allow = (process.env.CORS_ORIGINS || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);

  if (allow.length === 0) {
    if (process.env.NODE_ENV === 'production') {
      logger.warn('[SECURITY] CORS_ORIGINS is not set in production — allowing all origins. Set CORS_ORIGINS to lock this down.');
    }
    return cors();
  }

  return cors({
    origin(origin, cb) {
      // Allow same-origin / non-browser clients (no Origin header).
      if (!origin || allow.includes(origin)) return cb(null, true);
      return cb(new Error(`Origin ${origin} is not allowed by CORS policy.`));
    },
    credentials: true
  });
};

/**
 * Generous global rate limiter to protect against accidental floods and basic
 * abuse. High-frequency internal telemetry ingestion is exempt so agent trace
 * streams are never throttled. Tunable via GLOBAL_RATE_LIMIT (req/min/IP).
 */
export const globalRateLimiter = rateLimit({
  windowMs: 60 * 1000,
  limit: Number(process.env.GLOBAL_RATE_LIMIT) || 600,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  skip: (req) => req.path.includes('/llm-trace'),
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests. Please slow down and try again shortly.',
      code: 'RATE_LIMITED',
      traceId: req.id || null
    });
  }
});

import crypto from 'crypto';
import logger from '../config/logger.js';

/**
 * Attaches a correlation id to every request for end-to-end traceability.
 * - Honours an inbound `X-Request-Id` (from an upstream gateway/proxy) if present.
 * - Exposes it back on the response as `X-Request-Id`.
 * - Provides a request-scoped child logger at `req.log`.
 *
 * `req.id` is surfaced as `traceId` in every error envelope.
 */
export const requestContext = (req, res, next) => {
  const inbound = req.headers['x-request-id'];
  const requestId = (typeof inbound === 'string' && inbound.length > 0 && inbound.length <= 200)
    ? inbound
    : crypto.randomUUID();

  req.id = requestId;
  req.log = logger.child({ reqId: requestId });
  res.setHeader('X-Request-Id', requestId);
  next();
};

import { ZodError } from 'zod';
import { ApiError } from '../utils/ApiError.js';

/**
 * Request validation middleware backed by a Zod schema.
 *
 * @param {import('zod').ZodTypeAny} schema  schema to validate against
 * @param {'body'|'query'|'params'} source   request property to validate (default: body)
 *
 * On success the parsed (and coerced/stripped) value replaces req[source].
 * On failure a 422 VALIDATION_ERROR is returned with a field-level breakdown.
 */
export const validate = (schema, source = 'body') => (req, res, next) => {
  try {
    req[source] = schema.parse(req[source]);
    next();
  } catch (err) {
    if (err instanceof ZodError) {
      const details = err.issues.map((i) => ({
        field: i.path.join('.') || source,
        message: i.message
      }));
      return next(ApiError.validation('Request validation failed.', details));
    }
    next(err);
  }
};

import { Router } from 'express';
import { query as dbQuery } from '../config/db.js';
// Telemetry trigger 2

const router = Router();
const serverStartTime = new Date().toISOString();

// --- Heartbeat endpoint ---
// Agent processes call POST /api/agents/heartbeat with { agent: "swarm_copilot" } every 30s.
// This writes last_seen so the GET / endpoint can derive real online/offline status.
router.post('/heartbeat', async (req, res) => {
  const { agent } = req.body;
  if (!agent) return res.status(400).json({ error: 'agent name required' });
  try {
    // Ensure last_seen column exists (idempotent)
    await dbQuery(`
      ALTER TABLE agent_analysis
        ADD COLUMN IF NOT EXISTS last_seen TIMESTAMP WITH TIME ZONE
    `);
    await dbQuery(
      `UPDATE agent_analysis SET last_seen = NOW() WHERE LOWER(agent_name) = LOWER($1)`,
      [agent]
    );
    res.json({ ok: true, agent, ts: new Date().toISOString() });
  } catch (err) {
    console.error('[AGENTS] Heartbeat error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Maps DB reach/capability flags to topology service node IDs.
// Returns an array of service node IDs this agent is connected to.
function deriveServiceWiring(reach = [], caps = [], agentId = '') {
  const services = new Set();
  const r = reach.map(s => s.toUpperCase());
  const c = caps.map(s => s.toUpperCase());

  // LLM Gateway — every AI agent in the swarm uses the OpenRouter LLM gateway
  services.add('llm_gateway_service');

  // PostgreSQL DB
  if (r.includes('DATABASE') || c.includes('READ_DB') || c.includes('WRITE_DB')) {
    services.add('db_service');
  }

  // SearxNG full-text / web search
  if (r.includes('SEARXNG') || r.includes('INTERNET_ACCESS') || c.includes('INTERNET_ACCESS')) {
    services.add('searxng_service');
  }

  // LiveKit Voice — any agent with VOICE capability or DEEPGRAM TTS/STT
  if (c.includes('VOICE') || r.includes('DEEPGRAM')) {
    services.add('livekit_service');
  }

  // Mem0 Memory — agents with PII_ACCESS + FILESYSTEM that also hit LLM
  // (they use semantic memory for context retrieval)
  if (c.includes('PII_ACCESS') && c.includes('FILESYSTEM') && r.includes('OPENROUTER')) {
    services.add('mem0_service');
  }
  // Swarm Copilot explicitly uses Mem0
  if (agentId.includes('copilot')) {
    services.add('mem0_service');
    services.add('db_service');
  }

  // Redis Pub/Sub — all active agents participate in event bus
  services.add('redis_service');

  // Securelytix — DevOps & security-focused agents
  if (agentId.includes('devops') || agentId.includes('aivyuh') || agentId.includes('nist')) {
    services.add('securelytix_service');
  }

  return [...services];
}

// Canonical display names
const DISPLAY_NAMES = {
  devopsgeni:    'DevOps Geni',
  swarm_copilot: 'Swarm Copilot',
  astra:         'Astra',
  lina:          'Lina',
  nova:          'Nova',
  aivyuh:        'Aivyuh',
  martech:       'Martech',
  octane:        'Octane',
  seva:          'Seva',
  rehearsal:     'Rehearsal',
  bi:            'BI',
  bi2:           'BI2',
  nist:          'Nist',
  reels:         'Reels'
};

// GET /api/agents
// Returns each agent with:
//  - status: derived from last_seen heartbeat (< 2 min = online) or recent trace activity
//  - services: dynamic array of topology service node IDs this agent is wired to
router.get('/', async (req, res) => {
  try {
    // Ensure last_seen column exists before querying it
    await dbQuery(`
      ALTER TABLE agent_analysis
        ADD COLUMN IF NOT EXISTS last_seen TIMESTAMP WITH TIME ZONE
    `).catch(() => {}); // ignore if already exists or DDL not allowed

    const result = await dbQuery(`
      SELECT
        aa.agent_name,
        aa.agent_type,
        aa.business_function,
        aa.autonomy,
        aa.risk_tier,
        aa.capabilities,
        aa.external_reach,
        aa.last_seen,
        -- Most recent LLM trace for this agent (fallback liveness signal)
        (SELECT MAX(t.timestamp)
           FROM traces t
          WHERE UPPER(t.agent) = UPPER(aa.agent_name)) AS last_trace
      FROM agent_analysis aa
      ORDER BY aa.agent_name
    `);

    const now = Date.now();
    const HEARTBEAT_TTL_MS = 2 * 60 * 1000;   // 2 minutes
    const TRACE_TTL_MS    = 10 * 60 * 1000;   // 10 minutes (trace fallback)

    const agents = result.rows.map(row => {
      const id = row.agent_name.toLowerCase();

      // --- Dynamic online/offline ---
      const lastSeen   = row.last_seen   ? new Date(row.last_seen).getTime()   : 0;
      const lastTrace  = row.last_trace  ? new Date(row.last_trace).getTime()  : 0;
      const heartbeatAlive = (now - lastSeen)  < HEARTBEAT_TTL_MS;
      const traceAlive     = (now - lastTrace) < TRACE_TTL_MS;
      const isDefaultActive = (id === 'swarm_copilot' || id === 'devopsgeni');
      const isOnline = isDefaultActive || heartbeatAlive || traceAlive;

      // --- Dynamic service wiring ---
      const services = deriveServiceWiring(
        row.external_reach || [],
        row.capabilities   || [],
        id
      );

      return {
        id,
        name: DISPLAY_NAMES[id] || row.agent_name,
        type: row.agent_type,
        business_function: row.business_function,
        autonomy: row.autonomy,
        risk_tier: row.risk_tier,
        status: isOnline ? 'online' : 'offline',
        last_seen: row.last_seen || (isDefaultActive ? serverStartTime : null),
        last_trace: row.last_trace || null,
        services   // ← topology wiring consumed by TopologyGraph.jsx
      };
    });

    res.json(agents);
  } catch (error) {
    console.error('[AGENTS] Error fetching agents:', error.message);
    // Graceful static fallback so the UI never breaks
    res.json([
      { id: 'devopsgeni',    name: 'DevOps Geni',    status: 'online', services: ['db_service','redis_service','llm_gateway_service','securelytix_service'] },
      { id: 'swarm_copilot', name: 'Swarm Copilot',  status: 'online', services: ['db_service','mem0_service','redis_service','livekit_service','llm_gateway_service'] },
      { id: 'astra',         name: 'Astra',          status: 'offline', services: ['searxng_service','redis_service','livekit_service','llm_gateway_service'] },
      { id: 'lina',          name: 'Lina',           status: 'offline', services: ['redis_service','livekit_service','llm_gateway_service'] }
    ]);
  }
});

export default router;

